			setGeneratedBy(fieldNames.expressions[ctr], source);
			ctr++;
		}

		ann.memberValue = fieldNames;
		setGeneratedBy(ann, source);
		setGeneratedBy(ann.memberValue, source);
		return new Annotation[] { ann };
	}

